namespace {
bool almost_equal(double a,double b){return std::abs(a-b)<.001;}
Config quiet(float duration=.12f){Config c;c.duration=duration;c.boss_time=c.first_event_time=c.elite_interval=1e6f;c.max_enemies=0;c.item_drop_chance=0;return c;}
RunBonuses talents(){RunBonuses b;b.damage_bonus=.1f;b.crit_bonus=.06f;b.health_bonus=20;b.move_speed_bonus=.06f;b.xp_bonus=.1f;b.cooldown_reduction=.06f;b.upgrade_rerolls=2;b.death_protections=1;b.first_elite_reward=1;return b;}
void choose_all(Game& g){int limit=200;while(g.state==State::Upgrade){assert(--limit>0);assert(g.choose_upgrade(0));}}
void tick(Game& g,float seconds){for(int i=0;i<int(std::ceil(seconds/.01f));++i){g.update(.01f);choose_all(g);}}
void finish_timer(Game& g){for(int i=0;i<1000&&g.state==State::Playing;++i){g.update(.01f);choose_all(g);}assert(g.state==State::ChapterComplete||g.state==State::Victory);}
void strike(Game& g,EnemyKind kind,uint32_t id,float hp=1){Enemy e;e.id=id;e.kind=kind;e.hp=e.max_hp=hp;e.pos={220,0};e.speed=0;e.damage=0;g.enemies.push_back(e);Effect hit;hit.kind=EffectKind::Meteor;hit.pos=e.pos;hit.radius=30;hit.damage=hp+100;hit.duration=1;g.effects.push_back(hit);g.update(.01f);}
void kill_boss(Game& g){g.skills.fill(0);g.update(.01f);auto it=std::find_if(g.enemies.begin(),g.enemies.end(),[](const Enemy& e){return e.kind==EnemyKind::Boss;});assert(it!=g.enemies.end());Effect hit;hit.kind=EffectKind::Meteor;hit.pos=it->pos;hit.radius=100;hit.damage=1e8f;hit.duration=1;g.effects.push_back(hit);g.update(.01f);}
}
