 carry.gems.push_back({carry.player.pos,8,0});carry.update(.01f);assert(carry.state==State::Upgrade&&carry.reroll_upgrade());choose_all(carry);carry.skills.fill(0);carry.skills[int(Skill::Arrow)]=3;carry.skills[int(Skill::Pierce)]=2;
