 strike(carry,EnemyKind::Elite,100);choose_all(carry);assert(carry.metrics.first_elite_rewards==1&&carry.first_elite_reward_claimed&&carry.kills==1);carry.overcharge_levels=7;carry.vitality_levels=3;carry.passives[int(UpgradeKind::Health)]=2;carry.update(.01f);carry.player.hp=33;carry.fury_remaining=20;
 // XP already on the ground at the deadline must be selected before a checkpoint can exist.
