 RunBuild base;assert(carry.export_build(base));assert(base.intermission_choice==-1&&base.chapter_index==0&&base.kills==1&&base.metrics.enemy_kills_by_kind[int(EnemyKind::Elite)]==1&&base.upgrade_rerolls_remaining==1&&base.death_protections_remaining==0&&base.first_elite_reward_claimed);assert(almost_equal(base.completed_elapsed,carry.total_elapsed()));
 Game restored(quiet());for(int i=0;i<20;++i){assert(restored.restore_build(base));assert(restored.state==State::ChapterComplete&&!restored.advance_chapter());assert(restored.skills==base.skills&&restored.passives==base.passives&&restored.player.hp==base.hp&&restored.player.xp==base.xp&&restored.player.level==base.level&&restored.coins==base.coins);assert(restored.upgrade_rerolls_remaining==1&&restored.death_protections_remaining==0&&restored.metrics.death_protections_used==1&&restored.metrics.first_elite_rewards==1);assert(almost_equal(restored.total_elapsed(),base.completed_elapsed)&&restored.run_bonuses().health_bonus==20);assert(restored.fury_remaining==0);}
