  g.skills.fill(0);g.player.invulnerable=1e6f;g.update(.01f);auto boss=std::find_if(g.enemies.begin(),g.enemies.end(),[](const Enemy& e){return e.kind==EnemyKind::Boss;});assert(boss!=g.enemies.end());boss->pos={200,0};boss->speed=0;boss->attack_clock=100;g.update(.01f);bool found=false;for(const auto& e:g.effects)if(e.hostile&&e.enemy_kind==EnemyKind::Boss){assert(e.pattern==(chapter==0?0:chapter==1?2:1));found=true;}assert(found);
