 for(int chapter=0;chapter<3;++chapter){int preferred=0;for(int seed=1;seed<=80;++seed){Config c=quiet(1000);c.max_enemies=60;c.boss_time=900;c.first_event_time=.001f;Game g(c);if(chapter==0)g.start(CharacterClass::Mage,seed,{}, {RunMode::Campaign});else{RunBuild b=boundaries[chapter-1];b.seed=seed;assert(g.restore_build(b)&&g.advance_chapter());}g.update(.01f);auto k=g.special_event.kind;assert(k!=SpecialEventKind::None);if(chapter==0&&(k==SpecialEventKind::MushroomRush||k==SpecialEventKind::GuardedChest))++preferred;if(chapter==1&&(k==SpecialEventKind::Rift||k==SpecialEventKind::Fountain))++preferred;if(chapter==2&&(k==SpecialEventKind::EliteHunt||k==SpecialEventKind::BountyElite))++preferred;}assert(preferred>=28);}
